<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;class StoreTransportCalendarExceptionRequest extends FormRequest{public function authorize():bool{return$this->user()?->can('transporte.programacion.editar')??false;}public function rules():array{return['transport_route_id'=>['nullable',Rule::exists('transport_routes','id')->where(fn($q)=>$q->where('company_id',$this->user()->company_id))],'exception_date'=>'required|date','type'=>['required',Rule::in(array_keys(config('transport.exception_types')))],'reason'=>'required|string|max:1000','applies_to_all_routes'=>'nullable|boolean'];}protected function prepareForValidation():void{$this->merge(['applies_to_all_routes'=>$this->boolean('applies_to_all_routes')]);}}
